function rotr(x: i32, n: i32): i32 {
    return (x >>> n) | (x << (32 - n));
}

function sha256Block(message: buffer, roundK: buffer, out: buffer): i32 {
    const w = new Int32Array(64);
    const length = message.length;
    for (let i = 0; i < length; i = i + 1) {
        const word = i / 4;
        w[word] = w[word] | (message.charCodeAt(i) << ((3 - (i & 3)) * 8));
    }
    const padWord = length / 4;
    w[padWord] = w[padWord] | (0x80 << ((3 - (length & 3)) * 8));
    w[15] = length * 8;

    for (let t = 16; t < 64; t = t + 1) {
        const x = w[t - 15];
        const y = w[t - 2];
        const x7 = rotr(x, 7);
        const x18 = rotr(x, 18);
        const y17 = rotr(y, 17);
        const y19 = rotr(y, 19);
        const s0 = x7 ^ x18 ^ (x >>> 3);
        const s1 = y17 ^ y19 ^ (y >>> 10);
        w[t] = w[t - 16] + s0 + w[t - 7] + s1;
    }

    let a = 0x6a09e667;
    let b = 0xbb67ae85;
    let c = 0x3c6ef372;
    let d = 0xa54ff53a;
    let e = 0x510e527f;
    let f = 0x9b05688c;
    let g = 0x1f83d9ab;
    let h = 0x5be0cd19;
    for (let t = 0; t < 64; t = t + 1) {
        const a2 = rotr(a, 2);
        const a13 = rotr(a, 13);
        const a22 = rotr(a, 22);
        const e6 = rotr(e, 6);
        const e11 = rotr(e, 11);
        const e25 = rotr(e, 25);
        const sum0 = a2 ^ a13 ^ a22;
        const sum1 = e6 ^ e11 ^ e25;
        const choice = (e & f) ^ ((e ^ -1) & g);
        const majority = (a & b) ^ (a & c) ^ (b & c);
        const k = roundK.charCodeAt(2 * t) | (roundK.charCodeAt(2 * t + 1) << 16);
        const t1 = h + sum1 + choice + k + w[t];
        const t2 = sum0 + majority;

        h = g;
        g = f;
        f = e;
        e = d + t1;
        d = c;
        c = b;
        b = a;
        a = t1 + t2;
    }

    a = a + 0x6a09e667;
    b = b + 0xbb67ae85;
    c = c + 0x3c6ef372;
    d = d + 0xa54ff53a;
    e = e + 0x510e527f;
    f = f + 0x9b05688c;
    g = g + 0x1f83d9ab;
    h = h + 0x5be0cd19;
EOF
