  return [
    ['sha256Block', /let t = 0; t < 64/],
    ['chacha20Block', /let round = 0; round < 10/],
  ].map(([fn, header]) => {
    const lines = project.files.read('main.typed').split('\n');
    const begin = lines.findIndex(line => header.test(line)) + 1;
    const end = lines.findIndex((line, i) => i >= begin && line === '    }') + 1;
    const insns = image.insns(fn).filter(row => row.lines.some(line => line >= begin && line <= end));
    return { fn, copies: insns.filter(i => /^addi [^,]+, [^,]+, 0$/.test(i.text)).length,
      shifts: insns.filter(i => /^(slli?|srli?) /.test(i.text)).length,
      stackAccesses: insns.filter(i => /^(lw|sw).*\(sp\)$/.test(i.text)).length,
      calls: insns.filter(i => /^jal ra, /.test(i.text)).map(i => i.sym).slice(0, 8) };
  });
};
const baseline = summarize();
const speed = p.pipeline('speed');
return { baseline, revision: speed.rev, speed: summarize() };
`;
const wb = createWb({projects: [{id, files}]});
console.log(JSON.stringify(await wb.projects.open(id).run('inspect', {}, {fresh: true}), null, 2));
